import{c as e,Q as a,j as l,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"从选题到发布：dontbesilent 的 Claude Code 工作流","description":"","frontmatter":{"url":"https://x.com/dontbesilent/status/2017963276131598428","title":"从选题到发布：dontbesilent 的 Claude Code 工作流","author":"dontbesilent","archived":"2026-06-01T00:00:00.000Z","handle":"@dontbesilent","published":"2026-02-01T00:00:00.000Z","stats":"1713 likes · 301 retweets · 3390 bookmarks · 509587 views","type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-02-01-@dontbesilent-598428.md","filePath":"research/tweets/2026-02-01-@dontbesilent-598428.md","lastUpdated":1780990164000}'),n={name:"research/tweets/2026-02-01-@dontbesilent-598428.md"};function i(s,t,d,r,p,h){return a(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="从选题到发布-dontbesilent-的-claude-code-工作流-—-dontbesilent" tabindex="-1">从选题到发布：dontbesilent 的 Claude Code 工作流 — @dontbesilent <a class="header-anchor" href="#从选题到发布-dontbesilent-的-claude-code-工作流-—-dontbesilent" aria-label="Permalink to &quot;从选题到发布：dontbesilent 的 Claude Code 工作流 — @dontbesilent&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/dontbesilent/status/2017963276131598428" target="_blank" rel="noreferrer">https://x.com/dontbesilent/status/2017963276131598428</a><strong>作者</strong>：dontbesilent（@dontbesilent） <strong>發布日期</strong>：2026-02-01 <strong>收錄日期</strong>：2026-06-01 <strong>類型</strong>：Twitter Article <strong>統計</strong>：1713 likes · 301 retweets · 3390 bookmarks · 509587 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>由于流程太过复杂，本人不具备撰写能力，本文由 claude code 撰写。</p><p>[圖 1]</p><h1 id="为什么要看这篇文章" tabindex="-1">为什么要看这篇文章？ <a class="header-anchor" href="#为什么要看这篇文章" aria-label="Permalink to &quot;为什么要看这篇文章？&quot;">​</a></h1><p>很多人看到我的 Claude Code 工作目录截图后，第一反应是：「一个自媒体博主，至于搞这么复杂吗？」</p><p>但当我告诉他们，我用这套系统：</p><ul><li>年发 13,000 条内容</li><li>同时运营 7 个粉丝过万的平台</li><li>年涨粉 70 万</li></ul><p>他们的反应变成了：「能不能教教我？」</p><p>这篇文章就是答案。</p><h2 id="核心理念-从碎片到系统" tabindex="-1">核心理念：从碎片到系统 <a class="header-anchor" href="#核心理念-从碎片到系统" aria-label="Permalink to &quot;核心理念：从碎片到系统&quot;">​</a></h2><p>大多数人用 AI 的方式是：有个想法 → 问 AI → 得到答案 → 发布 → 忘记，下次又有想法 → 又问 AI → 又得到答案 → 又发布 → 又忘记。</p><p>这是碎片化创作，每次都在重新发明轮子。</p><p>我的方式是：有个想法 → 记录到选题库 → AI 帮我检索素材库 → 复用已验证的框架 → 发布 → 数据复盘 → 沉淀方法论。</p><p>这是系统化创作，每次创作都在给系统添砖加瓦。</p><h2 id="目录结构全景" tabindex="-1">目录结构全景 <a class="header-anchor" href="#目录结构全景" aria-label="Permalink to &quot;目录结构全景&quot;">​</a></h2><p>[圖 2]</p><h2 id="完整工作流-从想法到发布" tabindex="-1">完整工作流：从想法到发布 <a class="header-anchor" href="#完整工作流-从想法到发布" aria-label="Permalink to &quot;完整工作流：从想法到发布&quot;">​</a></h2><p><strong>第一步：选题记录（碎片想法管理）</strong> 当我有一个想法时，我会说：「记录选题」，AI 会自动把想法记录到 <code>01-内容生产/选题管理/00-选题记录.md</code>。这个文件是我的「想法收集箱」，所有碎片想法都先扔进来。</p><p><strong>第二步：选题深化（从想法到文稿）</strong> 当我决定深化某个选题时，AI 会：</p><ol><li>检索素材库（这是关键）—— 先查 核心概念库/，再查 金句库/，然后查 03-已发布的选题/</li><li>建议复用——如果找到相关内容，AI 会建议我复用，而不是重新创作</li><li>生成文稿——如果没有可复用的，AI 会基于我的风格生成新文稿，保存到 <code>01-待深化的选题/</code></li></ol><p><strong>第三步：标题与封面生成</strong> 文稿写好后，说「生成小红书标题+封面」，AI 会根据 <code>方法论沉淀/dontbesilent小红书标题方法论.md</code> 生成 3 个标题选项、封面文字建议、标题逻辑说明。</p><p><strong>第四步：短视频开头优化</strong> 如果是短视频，说「优化开头」，AI 会基于 <code>内容数据统计/dontbesilent 手动整理的短视频开头.xlsx</code> 的数据，优化前 5 秒的完播率。</p><p><strong>第五步：发布与数据记录</strong> 发布后，把文稿移动到 <code>03-已发布的选题/</code>，并记录发布时间、数据表现（播放量、点赞、评论）、复盘思考。这些数据会反哺到 <code>内容数据统计/</code> 和 <code>方法论沉淀/</code>。</p><h2 id="ai-自动化能力" tabindex="-1">AI 自动化能力 <a class="header-anchor" href="#ai-自动化能力" aria-label="Permalink to &quot;AI 自动化能力&quot;">​</a></h2><p>我给 AI 定义了一些自动化能力：</p><ul><li>记录选题：快速记录碎片想法</li><li>生成标题：基于方法论生成小红书标题</li><li>优化开头：提高短视频 5 秒完播率</li><li>检索素材：自动查找可复用的内容</li><li>数据复盘：记录发布数据并反哺方法论</li></ul><p>这些能力让 AI 不只是「回答问题」，而是「执行工作流」。</p><h2 id="素材库管理-从「碰运气」到「系统化」" tabindex="-1">素材库管理：从「碰运气」到「系统化」 <a class="header-anchor" href="#素材库管理-从「碰运气」到「系统化」" aria-label="Permalink to &quot;素材库管理：从「碰运气」到「系统化」&quot;">​</a></h2><p>这是整个系统的核心。</p><p>传统方式：每次写文稿都从零开始，不知道自己以前写过什么，好的表达、框架、案例都散落在各个文稿里。</p><p>我的方式：AI 写文稿前先检索素材库，找到相关内容后建议复用，每次创作都在给素材库添砖加瓦。</p><p>素材库结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内容素材库/</span></span>
<span class="line"><span>├── 核心概念库/     # 可复用的理论框架（如&quot;生产型兴趣&quot;）</span></span>
<span class="line"><span>├── 金句库/         # 高质量表达</span></span>
<span class="line"><span>├── 爆款文稿库/     # 已验证的内容结构</span></span>
<span class="line"><span>├── 100条思考系列/  # 从10894条推文中提取的100条思考</span></span>
<span class="line"><span>└── 推文库/         # 10894条推文原始数据</span></span></code></pre></div><p>举个例子：当我要写「如何用兴趣赚钱」这个选题时，AI 会：</p><ol><li>检索 <code>核心概念库/生产型兴趣.md</code></li><li>检索 <code>爆款文稿库/02-如何用兴趣赚钱并实现规模增长.md</code></li><li>告诉我：「你之前写过类似内容，要不要复用？」</li></ol><h2 id="数据驱动的方法论沉淀" tabindex="-1">数据驱动的方法论沉淀 <a class="header-anchor" href="#数据驱动的方法论沉淀" aria-label="Permalink to &quot;数据驱动的方法论沉淀&quot;">​</a></h2><p><code>内容数据统计/</code>：Dontbesilent 数据统计表.xlsx（所有内容数据）、dontbesilent 手动整理的短视频开头.xlsx（短视频开头完播率）</p><p><code>方法论沉淀/</code>：dontbesilent 小红书标题方法论.md（基于数据总结的标题规律）、选题/标题/开头的关系详解.md</p><p><code>选题研究/</code>：dan koe 热门选题/（对标 Dan Koe 的选题分析）、选题对比分析_流量好vs差vsDanKoe.md</p><p>每次发布后记录数据，反哺到方法论里，方法论是「活的」，会随着数据不断迭代。</p><h2 id="业务运营-内容只是手段-商业才是目的" tabindex="-1">业务运营：内容只是手段，商业才是目的 <a class="header-anchor" href="#业务运营-内容只是手段-商业才是目的" aria-label="Permalink to &quot;业务运营：内容只是手段，商业才是目的&quot;">​</a></h2><p><code>02-业务运营/</code> 记录收入数据与分析、业务逻辑与战略决策、各业务线的数据统计。内容是流量入口，业务是变现出口。</p><h2 id="核心价值-系统化-碎片化" tabindex="-1">核心价值：系统化 &gt; 碎片化 <a class="header-anchor" href="#核心价值-系统化-碎片化" aria-label="Permalink to &quot;核心价值：系统化 &gt; 碎片化&quot;">​</a></h2><ol><li><strong>记忆系统</strong>：AI 知道我以前写过什么，避免重复造轮子</li><li><strong>素材复用</strong>：好的框架、表达、案例，可以反复使用</li><li><strong>方法论沉淀</strong>：每次创作都在给系统添砖加瓦</li><li><strong>数据驱动</strong>：不是凭感觉，而是凭数据迭代</li></ol><h2 id="如何开始" tabindex="-1">如何开始？ <a class="header-anchor" href="#如何开始" aria-label="Permalink to &quot;如何开始？&quot;">​</a></h2><ol><li>先建立目录结构：按业务流程分类，不是按文件类型</li><li>再定义工作流：把重复的工作流程，教给 AI</li><li>然后建立素材库：把好的内容、框架、表达，沉淀下来</li><li>最后数据驱动：记录数据，反哺方法论</li></ol><h2 id="如何让-claude-code-帮你搭建这套系统" tabindex="-1">如何让 Claude Code 帮你搭建这套系统？ <a class="header-anchor" href="#如何让-claude-code-帮你搭建这套系统" aria-label="Permalink to &quot;如何让 Claude Code 帮你搭建这套系统？&quot;">​</a></h2><p>用户提示词模板：</p><blockquote><p>我想搭建一套像 dontbesilent 一样的内容生产系统。 我的基本情况：</p><ul><li>我做的内容类型是：[短视频/图文/音频]</li><li>我的平台是：[小红书/抖音/公众号/...]</li><li>我目前的痛点是：[每次都从零开始/找不到以前的素材/不知道什么选题好/...] 请帮我：</li></ul><ol><li>设计一个适合我的目录结构</li><li>建立素材库管理系统</li><li>定义我需要的 AI 自动化能力</li><li>创建 CLAUDE.md 项目指南（参考这篇文章的思路）</li></ol></blockquote><p>使用建议：先从小流程开始，边用边迭代，记录数据，定期复盘。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：年發 13,000 條/7 平台創作者用 Claude Code 搭建選題→素材→發布→數據→方法論的完整閉環，核心是 AI 記憶系統讓素材可復用。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>碎片化 → 系統化</strong>：不是「有想法→問 AI」，而是「想法→選題庫→素材復用→框架迭代」的閉環系統</li><li><strong>記憶系統是核心</strong>：10,894 條推文原始數據 + 核心概念庫/金句庫/爆款文稿庫，AI 知道你以前寫過什麼</li><li><strong>數據驅動方法論</strong>：每次發布後記錄數據反哺方法論，方法論是「活的」</li><li><strong>AI 執行工作流，非回答問題</strong>：定義自動化能力（記錄選題/生成標題/優化開頭/檢索素材）讓 Claude Code 成為流水線</li><li><strong>提供完整複製模板</strong>：文末附可直接使用的 prompt 模板，讓讀者搭建自己的系統</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>年發 13,000 條內容，同時運營 7 個粉絲過萬平台，年漲粉 70 萬</li><li>推文庫 10,894 條原始數據</li><li>工具：Claude Code、小紅書、抖音</li><li>素材庫結構：核心概念庫 / 金句庫 / 爆款文稿庫 / 100 條思考系列 / 推文庫</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>文章由 Claude Code 撰寫</strong>（文首自白），可操作性高但數字難以第三方驗證</li><li><strong>核心概念非原創</strong>：素材復用 + 數據驅動類似 PKM 領域（Obsidian/Zettelkasten）已有做法，AI 加持是增強而非革命</li><li><strong>適用範圍偏窄</strong>：適合高頻內容創作者，年 13,000 條的輸入規模才能充分啟動素材庫的網絡效應</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>提供完整目錄結構 + 可直接複製的 prompt 模板</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>系統化創作框架有新意，但 PKM 領域已有類似概念</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>具體數字（13K/7平台/70萬）有說服力，但自述難以驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>工作流描述清晰，但 CLAUDE.md/hook 設計細節缺失</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>創作者場景高度適用；知識工作者可借鑑框架但難直接套用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.3/10</strong></td><td>9×0.3+7×0.2+7×0.2+6×0.15+6×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：AI 執行工作流（非回答問題）的設計哲學 + 記憶系統 + 素材復用閉環，是可操作的 Claude Code workspace 設計原則。</p>`,66)])])}const b=e(n,[["render",i]]);export{u as __pageData,b as default};
